class Medikament {
    private String name;
    private double dosis;

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public double getDosis() {
        return dosis;
    }

    public void setDosis(double dosis) {
        if (dosis > 0 && dosis <= 500) {
            this.dosis = dosis;
        }
    }
